"""Classify only the exact EOF generated by an owned empty health-check socket."""
import io
import json
import socket
import tempfile
import time
from types import SimpleNamespace
import unittest
from unittest import mock

from test_security import ROOT, bare_manager, pm


class FrontProbeTests(unittest.TestCase):
    def setUp(self):
        scratch = ROOT / 'tests' / 'tmp'
        scratch.mkdir(exist_ok=True)
        self.temp = tempfile.TemporaryDirectory(dir=scratch)
        self.addCleanup(self.temp.cleanup)
        self.manager = bare_manager(self.temp.name)
        self.local, self.remote = '127.0.0.1:1860', '127.0.0.1:50220'

    def line(self, **changes):
        record = {'level': 'error', 'msg': 'EOF', 'service': 'test_only_http',
                  'listener': 'tcp', 'handler': 'http', 'kind': 'handler',
                  'local': self.local, 'client': self.remote, 'remote': self.remote}
        record.update(changes)
        return json.dumps(record)

    def record_probe(self, age=0):
        self.manager.front_probes[(self.local, self.remote)] = pm.time.monotonic() - age

    def child(self, argv=None, server_id=None):
        return pm.Child(argv or [str(ROOT / 'bin/gost'), '-C', '/test-only.json'],
                        'Test proxy', self.manager, 'test_only_http', server_id)

    def read(self, child, *lines):
        child.read_log(SimpleNamespace(stdout=io.BytesIO(('\n'.join(lines) + '\n').encode())))

    def test_health_probe_records_exact_socket_pair_before_close(self):
        probe = mock.MagicMock()
        probe.__enter__.return_value = probe
        probe.getpeername.return_value = ('127.0.0.1', 1860)
        probe.getsockname.return_value = ('127.0.0.1', 50220)

        def on_close(*_):
            self.assertIn((self.local, self.remote), self.manager.front_probes)

        probe.__exit__.side_effect = on_close
        with mock.patch.object(pm.socket, 'create_connection', return_value=probe) as connect:
            self.assertTrue(self.manager.front_probe(1860))
        connect.assert_called_once_with(('127.0.0.1', 1860), timeout=.2)
        self.assertTrue(self.manager.is_front_probe_eof(self.line()))
        self.assertFalse(self.manager.is_front_probe_eof(self.line()), 'A probe match must be consumed once')

    def test_owned_gost_probe_eof_never_sets_error_or_activity_entry(self):
        child = self.child()
        child.error = 'Earlier real upstream failure'
        self.record_probe()
        self.read(child, self.line())
        self.assertEqual(child.error, 'Earlier real upstream failure')
        self.assertFalse(self.manager.logs)

    def test_request_errors_remain_in_history_and_component_errors_remain_in_status(self):
        cases = [
            self.line(remote='127.0.0.1:50221', client='127.0.0.1:50221'),
            self.line(local='127.0.0.1:1861'),
            self.line(client='127.0.0.1:50221'),
            self.line(kind='listener', msg='listen tcp 127.0.0.1:1860: bind: address already in use'),
            self.line(msg='upstream EOF'),
            self.line(kind='dialer'),
            self.line(kind='service', sid='synthetic-request-id'),
            'EOF',
        ]
        for line in cases:
            with self.subTest(line=line):
                self.manager.logs.clear()
                self.record_probe()
                child = self.child()
                self.read(child, line)
                expected = json.loads(line)['msg'] if line.startswith('{') else line
                details = json.loads(line) if line.startswith('{') else {}
                request_error = (details.get('kind') in ('handler', 'dialer', 'connector')
                                 or details.get('kind') == 'service' and bool(details.get('sid')))
                self.assertEqual(child.error, '' if request_error else expected)
                self.assertEqual(len(self.manager.logs), 1)
                self.assertIn(expected, list(self.manager.logs)[0]['message'])

    def test_old_probe_and_non_owned_process_eof_are_never_filtered(self):
        self.record_probe(age=6)
        child = self.child()
        self.read(child, self.line())
        self.assertEqual(child.error, '')
        self.assertEqual(len(self.manager.logs), 1)
        for argv, server_id in [(['/usr/bin/ssh'], 'test_only_session'),
                                (['/different/installation/bin/gost'], None)]:
            with self.subTest(argv=argv):
                self.manager.logs.clear()
                self.record_probe()
                child = self.child(argv=argv, server_id=server_id)
                self.read(child, self.line())
                self.assertEqual(child.error, self.line())
                self.assertEqual(len(self.manager.logs), 1)

    def test_failed_probe_is_not_marked_healthy_and_old_records_are_pruned(self):
        self.record_probe(age=6)
        with mock.patch.object(pm.socket, 'create_connection', side_effect=socket.timeout):
            self.assertFalse(self.manager.front_probe(1860))
        self.assertFalse(self.manager.is_front_probe_eof(self.line()))
        self.record_probe(age=6)
        probe = mock.MagicMock()
        probe.__enter__.return_value = probe
        probe.getpeername.return_value = ('127.0.0.1', 1860)
        probe.getsockname.return_value = ('127.0.0.1', 50221)
        with mock.patch.object(pm.socket, 'create_connection', return_value=probe):
            self.assertTrue(self.manager.front_probe(1860))
        self.assertNotIn((self.local, self.remote), self.manager.front_probes)
        self.assertIn((self.local, '127.0.0.1:50221'), self.manager.front_probes)

    @unittest.skipUnless((ROOT / 'bin/gost').is_file(), 'Local GOST binary is not installed')
    def test_real_isolated_gost_keeps_client_eof_and_filters_its_own_probe(self):
        # This frontend only receives empty loopback sockets: no outbound request is made.
        port = pm.reserve_port({self.manager.port})
        config = self.manager.data / 'test-only-gost.json'
        pm.atomic_json(config, {'services': [{'name': 'test_only_http', 'addr': '127.0.0.1:' + str(port),
                                             'listener': {'type': 'tcp'}, 'handler': {'type': 'http'}}],
                                'log': {'level': 'error', 'output': 'stderr'}})
        child = self.child([str(ROOT / 'bin/gost'), '-C', str(config)])
        try:
            child.spawn()
            deadline = time.monotonic() + 3
            while not self.manager.front_probe(port):
                self.assertLess(time.monotonic(), deadline, 'Isolated GOST frontend did not bind')
                time.sleep(.02)
            time.sleep(.1)
            self.assertEqual(child.error, '')
            with socket.create_connection(('127.0.0.1', port), timeout=.2) as client:
                client_address = '%s:%s' % client.getsockname()[:2]
            deadline = time.monotonic() + 2
            while not any(log['level'] == 'error' for log in self.manager.logs):
                self.assertLess(time.monotonic(), deadline, 'A real client EOF was incorrectly filtered')
                time.sleep(.02)
            self.assertEqual(child.error, '')
            self.assertIn('EOF', list(self.manager.logs)[-1]['message'])
            self.assertNotIn(client_address, list(self.manager.logs)[-1]['message'])
            real_error = child.error
            self.assertTrue(self.manager.front_probe(port))
            time.sleep(.1)
            self.assertEqual(child.error, real_error)
            self.assertEqual(sum(log['level'] == 'error' for log in self.manager.logs), 1)
        finally:
            child.stop()
        self.assertFalse(pm.port_open(port))

    def test_gost_error_metadata_does_not_defeat_repeat_collapsing(self):
        child = self.child()
        self.read(child, self.line(msg='Upstream unavailable', time='2026-01-01T00:00:01Z'),
                  self.line(msg='Upstream unavailable', time='2026-01-01T00:00:02Z',
                            remote='127.0.0.1:50229'))
        rows = list(self.manager.logs)
        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0]['repeats'], 2)
        self.assertEqual(rows[0]['message'], 'Test proxy: Upstream unavailable')
        self.assertNotIn('50229', rows[0]['message'])

    def test_request_auth_error_does_not_block_the_proxy_but_fatal_and_bind_errors_persist(self):
        child = self.child()
        self.read(child, self.line(msg='Permission denied by upstream proxy'))
        self.assertEqual(child.error, '')
        self.assertFalse(child.blocked)
        self.read(child, self.line(kind='listener', msg='bind: address already in use'))
        self.assertEqual(child.error, 'bind: address already in use')
        self.read(child, self.line(kind='handler', level='fatal', msg='Test fatal component failure'))
        self.assertEqual(child.error, 'Test fatal component failure')


if __name__ == '__main__':
    unittest.main()
